INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D026_PROMO_RESOLUTION','Defence Resolution');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D026_PROMO_RESOLUTION_HELP','Choose one resolution when beginning play and each time you enter a new technological era. Prosperity grants +1 Gold and +1 Production per city. Enlightenment grants +1 Science and +1 Culture per city. Defence grants military units +10% Combat Strength.');
